const highlights = JSON.parse(localStorage.getItem('highlights')) || [];

function renderHighlights(data) {
    const container = document.getElementById('highlights');
    container.innerHTML = '';
    data.forEach((highlight, index) => {
        const div = document.createElement('div');
        div.className = 'highlight';
        div.textContent = `Streamer: ${highlight.streamer}, Game: ${highlight.game}, Score: ${highlight.score}`;
        container.appendChild(div);
    });
}

function applyFilters() {
    const gameFilter = document.getElementById('filter-game').value.toLowerCase();
    const streamerFilter = document.getElementById('filter-streamer').value.toLowerCase();
    const scoreFilter = parseInt(document.getElementById('filter-score').value, 10) || 0;

    const filtered = highlights.filter(h => 
        (!gameFilter || h.game.toLowerCase().includes(gameFilter)) &&
        (!streamerFilter || h.streamer.toLowerCase().includes(streamerFilter)) &&
        (h.score >= scoreFilter)
    ).sort((a, b) => b.score - a.score);

    renderHighlights(filtered);
}

document.getElementById('apply-filters').addEventListener('click', applyFilters);

document.getElementById('manual-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const streamer = document.getElementById('manual-streamer').value;
    const game = document.getElementById('manual-game').value;
    const score = parseInt(document.getElementById('manual-score').value, 10);

    highlights.push({ streamer, game, score });
    localStorage.setItem('highlights', JSON.stringify(highlights));
    applyFilters();
});

document.getElementById('export-results').addEventListener('click', () => {
    const blob = new Blob([JSON.stringify(highlights, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'highlights.json';
    a.click();
    URL.revokeObjectURL(url);
});

applyFilters();
